using Cmd = std::function<void(Session&)>;
std::map<std::string, Cmd> commands = {
    {"select", [](Session& s) { s.account = pick_account(); }},
    {"amount", [](Session& s) { s.amount  = read_amount(); }},
};
Step next(Step cur, Event e, const Session& s);   // the single decision point
auto it = commands.find(action_id(cur, e));
if (it != commands.end()) it->second(session);
Step new_step = next(session.step, e, session);
session.step = new_step;
show(view_id(new_step));                             // resolver, not the controller

